window.docContents[133].resolve({"/Performance/#performance":{"contents":"The translation performed by kernel_hom traverses the kernel expression twice (once to lift it to a common universe level, once to translate it into SFinKer) and builds, at each node, an instance of a translation lemma such as comp_hom or comp_lift. Two design choices keep this cheap.\n\n\n\n\n\n\n\n","context":"Kernel-Hom: Tactics for Kernel Categorical Reasoning","header":"8. Performance","id":"/Performance/#performance"}});